// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

export interface TicketStatusChangeOut {
  history_id: number;
  field: "status" | "payment_status" | "approval_lock";
  from_value: string | null;
  to_value: string;
  reason: string | null;
  changed_by: number | null;
  changed_by_name: string | null;
  changed_at: string;
}

export interface ReceptionDashboardOut {
  queues: QueueBoardOut[];
  deferred: OpdTicketOut[];
  /** Tickets locked by a pending refund, waiver or credit */
  awaiting_approval: OpdTicketOut[];
  cash_back_prompts: ReceptionCashBackOut[];
}

/** One live queue (a doctor's, or a department's for tickets without a doctor). */
export interface QueueBoardOut {
  queue_group: string;
  doctor_id: number | null;
  doctor_name: string | null;
  department_id: number | null;
  department_name: string | null;
  waiting: number;
  in_consultation: number;
  entries: QueueBoardEntryOut[];
}

export interface QueueBoardEntryOut {
  queue_id: number;
  ticket_id: number;
  ticket_number: string;
  token_no: number;
  patient_name: string;
  /** The ticket's status */
  status:
    | "Issued"
    | "Waiting"
    | "InConsultation"
    | "Examined"
    | "Completed"
    | "Deferred"
    | "Expired"
    | "Forfeited"
    | "Refunded"
    | "Void"
    | "Cancelled";
  priority: number;
  payment_status:
    | "Unpaid"
    | "PartiallyPaid"
    | "Paid"
    | "CreditAuthorized"
    | "Waivered"
    | "Refunded"
    | "PanelBilled";
  approval_lock: "None" | "RefundPending" | "WaiverPending" | "CreditPending";
}

/** An OPD ticket with its patient, doctor and department (service.TICKET_COLS). */
